import {
  View, Text, StyleSheet, TextInput, TouchableOpacity,
  ScrollView, Alert, SafeAreaView, KeyboardAvoidingView,
  Platform, StatusBar, ActivityIndicator
} from "react-native";
import { useEffect, useState } from "react";
import axios from "axios";
import { useRouter } from "expo-router";
import { Feather } from "@expo/vector-icons";
import AsyncStorage from "@react-native-async-storage/async-storage";

const COLORS = {
  dark: "#0a3d2e",    // Esmeralda Glaze
  accent: "#1f6f54",  // Acento
  light: "#94a3b8",   // Gris institucional
  bg: "#fcfdfd",      // Marfil suave
  border: "#f1f5f9"   // Líneas de división
};

export default function Perfil() {
  const router = useRouter();
  const [loading, setLoading] = useState(false);
  const [cargandoDatos, setCargandoDatos] = useState(true);
  
  // IMPORTANTE: El campo debe llamarse 'celular' para coincidir con tu Backend/DB
  const [usuario, setUsuario] = useState({
    id_usuario: null,
    nombre_completo: "",
    correo: "",
    celular: "", 
    direccion: ""
  });

  const [passwordData, setPasswordData] = useState({
    password_actual: "", 
    password: ""
  });

  useEffect(() => {
    cargarDatos();
  }, []);

  const cargarDatos = async () => {
    try {
      setCargandoDatos(true);
      const usuarioRaw = await AsyncStorage.getItem("usuario");
      if (!usuarioRaw) {
        setCargandoDatos(false);
        return;
      }
      const user = JSON.parse(usuarioRaw);
      
      // GET a /api/usuarios/:id (Pluralizado como en tu app.js actualizado)
      const res = await axios.get(`http://192.168.1.9:3000/api/usuarios/${user.id_usuario}`);
      
      setUsuario(res.data);
    } catch (error) {
      console.error("Error cargando perfil:", error);
      Alert.alert("Error", "No se pudo sincronizar la información del socio.");
    } finally {
      setCargandoDatos(false);
    }
  };

  const guardarCambios = async () => {
    if (!usuario.correo || !usuario.celular) {
      Alert.alert("Atención", "El correo y el celular son obligatorios.");
      return;
    }

    try {
      setLoading(true);
      
      // Enviamos 'celular' tal como lo espera el controlador
      const datosAActualizar = {
        correo: usuario.correo,
        celular: usuario.celular,
        direccion: usuario.direccion
      };

      console.log("📤 Enviando datos:", datosAActualizar);

      await axios.put(
        `http://192.168.1.9:3000/api/usuarios/actualizar/${usuario.id_usuario}`, 
        datosAActualizar
      );
      
      Alert.alert("GLAZE", "Información de socio actualizada correctamente.");
    } catch (error) {
      console.error("❌ Error en PUT:", error.response?.data);
      // Extraemos el error específico del backend (ej: "El correo ya está en uso")
      const msg = error.response?.data?.error || "No se pudo actualizar la información.";
      Alert.alert("Error", msg);
    } finally {
      setLoading(false);
    }
  };

  const actualizarPassword = async () => {
    if (!passwordData.password || !passwordData.password_actual) {
      Alert.alert("Atención", "Complete ambos campos de contraseña.");
      return;
    }
    try {
      setLoading(true);
      await axios.put(`http://192.168.1.9:3000/api/usuarios/password/${usuario.id_usuario}`, passwordData);
      Alert.alert("Seguridad", "Contraseña actualizada exitosamente.");
      setPasswordData({ password_actual: "", password: "" });
    } catch (error) {
      const msg = error.response?.data?.error || "La contraseña actual es incorrecta.";
      Alert.alert("Error de Seguridad", msg);
    } finally {
      setLoading(false);
    }
  };

  return (
    <SafeAreaView style={styles.mainWrapper}>
      <StatusBar barStyle="dark-content" />
      
      <View style={styles.navHeader}>
        <TouchableOpacity onPress={() => router.back()} style={styles.backBtn}>
          <Feather name="chevron-left" size={24} color={COLORS.dark} />
        </TouchableOpacity>
        <Text style={styles.navTitle}>CUENTA PRIVADA</Text>
        <View style={{ width: 40 }} /> 
      </View>

      <KeyboardAvoidingView behavior={Platform.OS === "ios" ? "padding" : "height"} style={{ flex: 1 }}>
        <ScrollView style={styles.container} showsVerticalScrollIndicator={false}>
          
          <View style={styles.headerSection}>
            <Text style={styles.brandTitle}>Gestión de Perfil</Text>
            <View style={styles.accentLine} />
            <Text style={styles.brandSubtitle}>CONFIGURACIÓN DE SEGURIDAD Y DATOS</Text>
          </View>

          {cargandoDatos ? (
            <ActivityIndicator size="large" color={COLORS.dark} style={{ marginTop: 50 }} />
          ) : (
            <>
              {/* BLOQUE: INFORMACIÓN PERSONAL */}
              <View style={styles.glazeCard}>
                <View style={styles.sideIndicator} />
                <View style={styles.cardPadding}>
                  <Text style={styles.sectionLabel}>INFORMACIÓN DEL TITULAR</Text>

                  <View style={styles.inputBox}>
                    <Text style={styles.fieldLabel}>NOMBRE COMPLETO (Socio Glaze)</Text>
                    <TextInput
                      style={[styles.input, styles.inputBlocked]}
                      value={usuario.nombre_completo ? usuario.nombre_completo.toUpperCase() : "IDENTIDAD NO CARGADA"}
                      editable={false}
                    />
                  </View>

                  <View style={styles.inputBox}>
                    <Text style={styles.fieldLabel}>CORREO ELECTRÓNICO</Text>
                    <TextInput
                      style={styles.input}
                      value={usuario.correo}
                      onChangeText={(t) => setUsuario({...usuario, correo: t})}
                      placeholder="ejemplo@glaze.com"
                      placeholderTextColor={COLORS.light}
                      keyboardType="email-address"
                      autoCapitalize="none"
                    />
                  </View>

                  <View style={styles.inputBox}>
                    <Text style={styles.fieldLabel}>TELÉFONO CELULAR</Text>
                    <TextInput
                      style={styles.input}
                      value={usuario.celular} // Usando 'celular' correctamente
                      onChangeText={(t) => setUsuario({...usuario, celular: t})}
                      keyboardType="numeric"
                      placeholder="300 000 0000"
                    />
                  </View>

                  <View style={styles.inputBox}>
                    <Text style={styles.fieldLabel}>DIRECCIÓN DE RESIDENCIA</Text>
                    <TextInput
                      style={styles.input}
                      value={usuario.direccion}
                      onChangeText={(t) => setUsuario({...usuario, direccion: t})}
                      placeholder="Calle 123 #45-67"
                    />
                  </View>

                  <TouchableOpacity style={styles.btnMain} onPress={guardarCambios} disabled={loading}>
                    {loading ? <ActivityIndicator color="white" /> : <Text style={styles.btnMainText}>GUARDAR CAMBIOS</Text>}
                  </TouchableOpacity>
                </View>
              </View>

              {/* BLOQUE: SEGURIDAD */}
              <View style={styles.glazeCard}>
                <View style={[styles.sideIndicator, { backgroundColor: COLORS.light }]} />
                <View style={styles.cardPadding}>
                  <Text style={styles.sectionLabel}>SEGURIDAD DE LA BÓVEDA</Text>

                  <View style={styles.inputBox}>
                    <Text style={styles.fieldLabel}>CONTRASEÑA ACTUAL</Text>
                    <TextInput
                      style={styles.input}
                      secureTextEntry
                      value={passwordData.password_actual}
                      onChangeText={(t) => setPasswordData({...passwordData, password_actual: t})}
                    />
                  </View>

                  <View style={styles.inputBox}>
                    <Text style={styles.fieldLabel}>NUEVA CONTRASEÑA</Text>
                    <TextInput
                      style={styles.input}
                      secureTextEntry
                      value={passwordData.password}
                      onChangeText={(t) => setPasswordData({...passwordData, password: t})}
                    />
                  </View>

                  <TouchableOpacity style={styles.btnSecondary} onPress={actualizarPassword} disabled={loading}>
                    <Text style={styles.btnSecondaryText}>ACTUALIZAR CREDENCIALES</Text>
                  </TouchableOpacity>
                </View>
              </View>
            </>
          )}

          <View style={{ height: 40 }} />
        </ScrollView>
      </KeyboardAvoidingView>
    </SafeAreaView>
  );
}

